var tickets = pgTable("tickets", {
  id: serial("id").primaryKey(),
  eventId: integer("event_id").notNull(),
  name: text("name").notNull(),
  // e.g., "VIP", "General Admission", "Bottle Service"
  description: text("description"),
  price: integer("price").notNull(),
  quantity: integer("quantity").notNull(),
  remainingQuantity: integer("remaining_quantity"),
  isActive: boolean("is_active").default(true),
  status: text("status").default("on_sale"),
  // on_sale, off_sale, sold_out, staff_only
  priceType: text("price_type").default("standard"),
  // standard, pay_what_you_can
  minPerOrder: integer("min_per_order").default(1),
  maxPerPurchase: integer("max_per_purchase").default(10),
  displayRemainingQuantity: boolean("display_remaining_quantity").default(true),
  hideIfSoldOut: boolean("hide_if_sold_out").default(false),
  hidePriceIfSoldOut: boolean("hide_price_if_sold_out").default(false),
  secretCode: text("secret_code"),
  // Access code to see/purchase this ticket
  salesStartDate: timestamp("sales_start_date"),
  salesStartTime: text("sales_start_time"),
  salesEndDate: timestamp("sales_end_date"),
  salesEndTime: text("sales_end_time"),
  hideBeforeSalesStart: boolean("hide_before_sales_start").default(false),
  hideAfterSalesEnd: boolean("hide_after_sales_end").default(false),
  // Lock condition: Requires another ticket to be in cart before this can be purchased
  lockMinQuantity: integer("lock_min_quantity"),
  lockTicketTypeId: integer("lock_ticket_type_id"),
  // Advanced ticket features
  tierLevel: text("tier_level").default("standard"),
  // standard, premium, vip, ultra_vip
  benefits: text("benefits").array(),
  // Array of benefits/features
  badgeColor: text("badge_color").default("#3b82f6"),
  // Color for tier badge
  badgeIcon: text("badge_icon").default("ticket"),
  // Icon for tier badge
  includedItems: text("included_items").array(),
  // What's included with this ticket
  transferable: boolean("transferable").default(true),
  // Can ticket be transferred
  refundable: boolean("refundable").default(false),
  // Can ticket be refunded
  earlyAccess: boolean("early_access").default(false),
  // Early entry privilege
  prioritySupport: boolean("priority_support").default(false),
  // Priority customer support
  exclusiveContent: boolean("exclusive_content").default(false),
  // Access to exclusive content
  meetGreet: boolean("meet_greet").default(false),
  // Meet & greet access
  backstageAccess: boolean("backstage_access").default(false),
  // Backstage access
  seatingPriority: text("seating_priority").default("general"),
  // general, reserved, premium, vip
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});
var insertTicketSchema = createInsertSchema(tickets).pick({
  eventId: true,
  name: true,
  description: true,
  price: true,
  quantity: true,
  remainingQuantity: true,
  isActive: true,
  status: true,
  priceType: true,
  minPerOrder: true,
  maxPerPurchase: true,
  displayRemainingQuantity: true,
  hideIfSoldOut: true,
  hidePriceIfSoldOut: true,
  secretCode: true,
  salesStartTime: true,
  salesEndTime: true,
  hideBeforeSalesStart: true,
  hideAfterSalesEnd: true,
  lockMinQuantity: true,
  lockTicketTypeId: true,
  tierLevel: true,
  benefits: true,
  badgeColor: true,
  badgeIcon: true,
  includedItems: true,
  transferable: true,
  refundable: true,
  earlyAccess: true,
  prioritySupport: true,
  exclusiveContent: true,
  meetGreet: true,
  backstageAccess: true,
  seatingPriority: true
}).extend({
  // Handle dates as strings and convert them in the transform
  salesStartDate: external_exports.string().nullable().optional(),
  salesEndDate: external_exports.string().nullable().optional(),
  // Ensure arrays are properly handled
  benefits: external_exports.array(external_exports.string()).optional(),
  includedItems: external_exports.array(external_exports.string()).optional(),
  tierLevel: external_exports.enum(["standard", "premium", "vip", "ultra_vip"]).default("standard"),
  seatingPriority: external_exports.enum(["general", "reserved", "premium", "vip"]).default("general")
}).transform((data) => {
  return {
    ...data,
    salesStartDate: data.salesStartDate ? new Date(data.salesStartDate) : null,
    salesEndDate: data.salesEndDate ? new Date(data.salesEndDate) : null
  };
});
